arguments.command:
cd /workspace/project && python3 - <<'PY'
import re
s=open('src/star4_switch.c').read()

# remove the broken helper
start=s.index('static void emit_generated_data')
end=s.index('/* ------------------------------ certificates')
s=s[:start]+s[end:]

# fix send_ack_to leftover
s=s.replace("""static bool send_ack_to(collector_t *c, int rank, uint32_t prefix) {
    const epic_port_t dummy;
    (void)dummy;
    size_t len""","""static bool send_ack_to(collector_t *c, int rank, uint32_t prefix) {
    size_t len""")

# fix train data emission calls
s=s.replace("""                    build_payload_words(c, ev->seed, p, r, c->out);
                    emit_generated_data(c, r, p, ev->seed, NULL, ev->xors, 0);""",
"""                    build_payload_words(c, ev->seed, p, r, c->out);
                    size_t len = epic_build_roce_data_raw(
                        c->inb, sizeof(c->inb), c->mac_host[r], c->mac_sw[r], c->ip_host[r],
                        c->ip_sw[r], EPIC_ROCE_UDP_PORT, EPIC_ROCE_UDP_PORT, 0x200u + (uint32_t)r,
                        (c->start + p) & M24, c->out, c->plen);
                    if (!len) {
                        continue;
                    }
                    ingress_frame(c, r, c->inb, len);""")

# htonl helper
s=s.replace("""#define M24 0x00ffffffu
#define MAX_FRAME EPIC_MAX_FRAME_BYTES""","""#define M24 0x00ffffffu
#define MAX_FRAME EPIC_MAX_FRAME_BYTES

static uint32_t be32(uint32_t host) {
    uint8_t b[4] = {(uint8_t)(host >> 24), (uint8_t)(host >> 16), (uint8_t)(host >> 8), (uint8_t)host};
    uint32_t out;
    memcpy(&out, b, 4);
    return out;
}""")
s=s.replace("htonl_safe(","be32(")
open('src/star4_switch.c','w').write(s)
PY
grep -n "emit_generated_data\|htonl_safe\|dummy" src/star4_switch.c; echo "---"; grep -c "" src/star4_switch.c
